'use strict';

function parseLedger(text) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  const values = new Map();
  for (const fragment of text.split(';')) {
    const match = /^\s*([A-Za-z][A-Za-z0-9_]*)\s*=\s*([+-]?\d+)\s*$/.exec(fragment);
    if (!match) continue;
    const value = Number(match[2]);
    if (!Number.isSafeInteger(value)) continue;
    values.set(match[1], value);
  }
  const entries = Array.from(values, ([key, value]) => ({ key, value }));
  if (entries.length === 0) return { entries, total: 0, minimum: null, maximum: null, mean: null };
  const numbers = entries.map((entry) => entry.value);
  const total = numbers.reduce((sum, value) => sum + value, 0);
  return {
    entries,
    total,
    minimum: Math.min(...numbers),
    maximum: Math.max(...numbers),
    mean: total / numbers.length
  };
}

module.exports = { parseLedger };

