'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['parseLedger']);
const { parseLedger } = api;

assert.deepStrictEqual(parseLedger(''), {
  entries: [], total: 0, minimum: null, maximum: null, mean: null
});
assert.deepStrictEqual(parseLedger(' ; nonsense ; =4 ; 9bad=2 ; ok=1.5 '), {
  entries: [], total: 0, minimum: null, maximum: null, mean: null
});

const result = parseLedger(' alpha = +3 ; beta=-2; ignored ; alpha = 7 ; _bad=5; gamma_2 = 0 ');
assert.deepStrictEqual(result, {
  entries: [
    { key: 'beta', value: -2 },
    { key: 'alpha', value: 7 },
    { key: 'gamma_2', value: 0 }
  ],
  total: 5,
  minimum: -2,
  maximum: 7,
  mean: 5 / 3
});

assert.deepStrictEqual(parseLedger('a=1;b=2;a=bad;c=3'), {
  entries: [{ key: 'a', value: 1 }, { key: 'b', value: 2 }, { key: 'c', value: 3 }],
  total: 6,
  minimum: 1,
  maximum: 3,
  mean: 2
});
assert.deepStrictEqual(parseLedger('a=1;b=2;a=4'), {
  entries: [{ key: 'b', value: 2 }, { key: 'a', value: 4 }],
  total: 6,
  minimum: 2,
  maximum: 4,
  mean: 3
});

const safe = Number.MAX_SAFE_INTEGER;
assert.deepStrictEqual(parseLedger(`min=${Number.MIN_SAFE_INTEGER};max=+${safe};unsafe=${safe + 1}`), {
  entries: [{ key: 'min', value: Number.MIN_SAFE_INTEGER }, { key: 'max', value: safe }],
  total: 0,
  minimum: Number.MIN_SAFE_INTEGER,
  maximum: safe,
  mean: 0
});

assert.deepStrictEqual(parseLedger('A1=01;z_9=-0; bad-key=4; x=3 trailing'), {
  entries: [{ key: 'A1', value: 1 }, { key: 'z_9', value: -0 }],
  total: 1,
  minimum: -0,
  maximum: 1,
  mean: 0.5
});

const first = parseLedger('a=1');
const second = parseLedger('a=1');
assert.notStrictEqual(first.entries, second.entries);
assert.notStrictEqual(first.entries[0], second.entries[0]);
first.entries[0].value = 99;
assert.deepStrictEqual(second.entries, [{ key: 'a', value: 1 }]);

for (const bad of [null, undefined, 4, {}, [], new String('a=1')]) {
  assert.throws(() => parseLedger(bad), TypeError);
}

